// Curated stops — central Barcelona only (MVP). Spread across neighbourhoods
// on purpose, rather than piling everyone into the same few hotspots.
// Shared by index.html and scripts/generate.mjs.
window.WALKBCN_STOPS = [
  { id: 'sagrada-familia', name: 'Sagrada Família', img: "SF maig 2 cropped.jpg", area: 'Eixample', lat: 41.4036, lng: 2.1744, tags: ['architecture','history'], crowded: true,
    story: "In 1882 a modest neo-Gothic church began here. A year later a young architect named Antoni Gaudí took over, and threw out the plan. He spent the next 43 years on it, living in his workshop near the end. When asked why it was taking so long, he said: my client is not in a hurry. Look up at the columns — they branch like trees, because Gaudí wanted the inside to feel like a forest.",
    tip: "Walk around to the Passion façade side — it's calmer and the sculpture is stark and striking." },
  { id: 'recinte-modernista-de-sant-pau', name: 'Recinte Modernista de Sant Pau', img: "Hospital Sant Pau, main facade.jpg", area: 'El Guinardó', lat: 41.4114, lng: 2.1744, tags: ['architecture','history'],
    story: "This looks like a fairytale town, but it was a working hospital until 2009. Architect Lluís Domènech i Montaner believed beauty helped people heal, so he gave patients gardens, light, and colourful tiled pavilions. Underneath, a network of tunnels moved patients and supplies, so the gardens stayed peaceful above.",
    tip: "Sagrada Família is a straight 10-minute walk down Avinguda de Gaudí." },
  { id: 'casa-mila', name: 'Casa Milà (La Pedrera)', img: "Casa Milà, general view.jpg", area: 'Eixample', lat: 41.3954, lng: 2.1620, tags: ['architecture','art'], crowded: true,
    story: "Locals mocked this building when it opened in 1912, calling it La Pedrera — the stone quarry. There isn't a single straight wall on the façade. The wrought-iron balconies look like seaweed, and up on the roof stand chimneys shaped like helmeted warriors. Some say they inspired the look of Darth Vader.",
    tip: "Even from the street, check the iron balconies up close — each one is different." },
  { id: 'casa-batllo', name: 'Casa Batlló', img: "Casa Batllo Overview Barcelona Spain cut.jpg", area: 'Eixample', lat: 41.3916, lng: 2.1650, tags: ['architecture','art'], crowded: true,
    story: "Look at the roof: it rises like the scaly back of a dragon, and the tower is the sword of Sant Jordi, Catalonia's patron saint, plunged into it. The balconies resemble skulls and the columns look like bones, which is why some call this the House of Bones. Gaudí rebuilt an ordinary house into a legend.",
    tip: "Next door is Casa Amatller, by a rival architect — this block is nicknamed the Block of Discord." },
  { id: 'mercat-de-la-llibertat', name: 'Mercat de la Llibertat', img: "J23 525e Mercado de la Libertad.jpg", area: 'Gràcia', lat: 41.3998, lng: 2.1528, tags: ['food','local'],
    story: "Gràcia was its own town until 1897, and it still behaves like one. This iron-and-glass market from 1888 is where the neighbourhood actually shops. Notice how stallholders know their customers by name. If you buy something, try some local cheese or a paper cone of olives — and say bon dia.",
    tip: "Mornings are busiest with locals; keep the aisles clear and buy something if you linger." },
  { id: 'placa-del-sol', name: 'Plaça del Sol', img: "Young adults sit and talk in Plaza del Sol in Barcelona.jpg", area: 'Gràcia', lat: 41.4013, lng: 2.1576, tags: ['local','history'],
    story: "This square has been a meeting point for Gràcia's neighbours for generations. During the Spanish Civil War, a bomb shelter was dug beneath it. Today it's where people gather after work for a drink in the sun. Gràcia's squares are its living rooms — and it's people's home, so evenings here are best enjoyed quietly.",
    tip: "Residents live right above the terraces: keep voices down late at night." },
  { id: 'palau-de-la-musica-catalana', name: 'Palau de la Música Catalana', img: "22 11 01 Palau DSCF2611 52502512616 cc1e7db845 k.jpg", area: 'Sant Pere', lat: 41.3876, lng: 2.1753, tags: ['architecture','art','culture'],
    story: "Built in 1908 for a working-class choir, this concert hall is a celebration of Catalan identity. The façade features busts of Bach, Beethoven and Wagner, and a sculpture of Catalan folk song. Inside, an enormous stained-glass skylight glows like a sun above the audience. It's the only concert hall in Europe lit entirely by natural light during the day.",
    tip: "Look for the mosaic columns on the corner — each has a different floral pattern." },
  { id: 'mercat-de-santa-caterina', name: 'Mercat de Santa Caterina', img: "Market Roof (5832285437) (2).jpg", area: 'Sant Pere', lat: 41.3862, lng: 2.1786, tags: ['food','architecture'],
    story: "That wavy, colourful roof is made from over 300,000 ceramic tiles, in the colours of fruit and vegetables sold below. The market is the oldest covered one in the city, built on the site of a medieval convent. When it was renovated in 2005, archaeologists found the convent's foundations — you can still see them inside.",
    tip: "A good local alternative to the crowded Boqueria — same quality, far fewer queues." },
  { id: 'barcelona-cathedral', name: 'Barcelona Cathedral', img: "Barcelona Cathedral Saint Eulalia.jpg", area: 'Gothic Quarter', lat: 41.3840, lng: 2.1762, tags: ['history','architecture'], crowded: true,
    story: "The cathedral took over 600 years to finish — the main façade was only completed in the late 1800s. Step into the cloister and you'll hear geese. There are always thirteen of them, one for each year of Saint Eulàlia's life. She was a young martyr from Roman times, and the city's original patron saint.",
    tip: "On Sunday mornings locals dance the sardana in the square in front." },
  { id: 'placa-del-rei', name: 'Plaça del Rei', img: "Palau Reial Major 2574.jpg", area: 'Gothic Quarter', lat: 41.3842, lng: 2.1774, tags: ['history'],
    story: "This was the courtyard of the Counts of Barcelona. Legend says that on these steps Ferdinand and Isabella welcomed Christopher Columbus home from his first voyage in 1493. Beneath your feet, two thousand years ago, lay the Roman town of Barcino — streets, a laundry, even a wine factory, which you can still visit underground.",
    tip: "The City History Museum (MUHBA) entrance is right here if you want to see Roman Barcino." },
  { id: 'santa-maria-del-mar', name: 'Santa Maria del Mar', img: "Santa Maria del Mar, Barcelona 05.jpg", area: 'El Born', lat: 41.3838, lng: 2.1820, tags: ['history','architecture','culture'],
    story: "This is the cathedral of the people. It was built in just 54 years by the dock workers and fishermen of the neighbourhood. The bastaixos, the porters, carried every stone on their backs from the quarry at Montjuïc. Look for small carved figures of them on the main doors. Inside, the columns are so slender the space feels weightless.",
    tip: "Entry to the basilica is usually free at set times — check the door." },
  { id: 'museu-picasso', name: 'Museu Picasso', img: "Museu Picasso Barcelona.jpg", area: 'El Born', lat: 41.3852, lng: 2.1808, tags: ['art','history'],
    story: "Picasso arrived in Barcelona aged 13 and grew up as an artist on these streets. The museum fills five medieval palaces on Carrer Montcada, the street where wealthy merchants once lived. Inside, you'll see how a teenage prodigy who painted like an old master slowly broke every rule he'd learned.",
    tip: "Free entry on Thursday evenings and the first Sunday of the month (book ahead)." },
  { id: 'el-born-centre-de-cultura', name: 'El Born Centre de Cultura', img: "El BornCC setembre 2013 (2).JPG", area: 'El Born', lat: 41.3856, lng: 2.1840, tags: ['history'],
    story: "Under this old market roof lies an entire neighbourhood frozen in time. In 1714, after Barcelona fell in the War of the Spanish Succession, these streets were demolished to build a fortress. When workers dug here in 2002, they found the houses, wells and streets just as they were left. Every 11 September, Catalonia's national day remembers that defeat.",
    tip: "Entry to the central area overlooking the ruins is free." },
  { id: 'macba', name: 'MACBA', img: "Barcelona - Museu d'Art Contemporani de Barcelona (MACBA).jpg", area: 'El Raval', lat: 41.3833, lng: 2.1668, tags: ['art','local'],
    story: "This bright white museum of contemporary art was designed by Richard Meier and dropped into one of the city's oldest, densest neighbourhoods. The square outside became something nobody planned: one of Europe's most famous skateboarding spots. Stand for a minute and listen — wheels on stone is the soundtrack here.",
    tip: "Respect the skaters' space, and wander the Raval's side streets for small independent galleries." },
  { id: 'mercat-de-sant-antoni', name: 'Mercat de Sant Antoni', img: "Mercat de Sant Antoni, Barcelona.jpg", area: 'Sant Antoni', lat: 41.3786, lng: 2.1622, tags: ['food','local'],
    story: "This huge cross-shaped market reopened in 2018 after nine years of restoration. During the works they uncovered part of the 17th-century city wall, now visible in the basement. On Sunday mornings the outer ring turns into a second-hand book, comic and stamp market, where collectors have been swapping since the 1930s.",
    tip: "Come on a Sunday morning for the book market, then join the locals for vermut nearby." },
  { id: 'carrer-de-blai', name: 'Carrer de Blai', img: "Poble Sec capvespre.jpg", area: 'Poble-sec', lat: 41.3734, lng: 2.1636, tags: ['food','local'],
    story: "This pedestrian street is lined with pintxo bars: small bites on bread, held together with a toothpick. Grab what you like from the bar, and at the end they count your toothpicks to make the bill. Poble-sec was a working-class neighbourhood built for the people of the port and the theatres of the nearby Paral·lel.",
    tip: "Weekday early evenings are more relaxed — and keep it quiet, people live upstairs." },
  { id: 'parc-de-la-ciutadella', name: 'Parc de la Ciutadella', img: "Ciutadella Park fountain.jpg", area: 'Ciutadella', lat: 41.3881, lng: 2.1873, tags: ['outdoors','history'],
    story: "Remember that fortress built after 1714? This is where it stood — for 150 years, a symbol of occupation. When it was finally torn down, the people turned it into the city's first public park. The monumental fountain was worked on by a young student called Antoni Gaudí. Today it's where Barcelona plays: jugglers, drummers and picnics.",
    tip: "Rent a rowing boat on the small lake, or just find shade under the palms." },
  { id: 'barceloneta-beach', name: 'Barceloneta beach', img: "Platja de la Barceloneta 02.jpg", area: 'La Barceloneta', lat: 41.3784, lng: 2.1925, tags: ['outdoors','local'], crowded: true,
    story: "Barceloneta was built in the 1750s for fishermen and families who lost their homes when the Ribera was demolished. Its narrow streets are lined with tiny flats, laundry on the balconies. The beach as you see it was largely created for the 1992 Olympics, when the city finally turned to face the sea.",
    tip: "Wear a top when walking through the neighbourhood streets — it's a local request, and the law." },
  { id: 'park-guell', name: 'Park Güell', img: "Parc guell - panoramio.jpg", area: 'Gràcia', lat: 41.4145, lng: 2.1527, tags: ['outdoors','architecture','art'], crowded: true,
    story: "This was meant to be a luxury housing estate for sixty families. Only two houses were ever sold — one to Gaudí himself. The project failed, but the city gained a park. The famous serpentine bench was designed to fit the curve of a seated body; legend says a worker sat naked in wet plaster to get the shape right.",
    tip: "Book a timed ticket for the monumental zone — the forest paths above are free." },
  // Added after Session 8: more stops so routes by time, distance and start point have enough options.
  { id: "arc-de-triomf", name: "Arc de Triomf", img: "Arc de Triomf, Barcelona 2716.jpg", area: "Sant Pere", lat: 41.3921, lng: 2.1809, tags: ["architecture", "history", "outdoors"],
    story: "This red-brick arch was not built to celebrate a battle. It was the grand entrance to the 1888 Universal Exhibition, Barcelona's first world fair, designed by the architect Josep Vilaseca. Look closely at the brickwork and you'll spot Moorish-style patterns, a nod to Spain's Islamic heritage, while the carved friezes welcome visitors to the city. From here, the wide promenade leads straight to Parc de la Ciutadella, where the exhibition itself was held.",
    tip: "Walk down the promenade towards Ciutadella: it's one of the most pleasant short walks in the city." },
  { id: "placa-reial", name: "Plaça Reial", img: "Barcelona - Plaça Reial - View SSE.jpg", area: "Gothic Quarter", lat: 41.3801, lng: 2.1753, tags: ["architecture", "local", "history"], crowded: true,
    story: "This elegant arcaded square was built in the 19th century on land where a convent once stood. Look at the tall iron lampposts with their helmets and curling arms: they were among the first public works of a young Antoni Gaudí, long before the Sagrada Família. Palm trees, a central fountain and the cafés under the arches make it feel like an outdoor living room, busy from morning coffee to late at night.",
    tip: "People live in the flats above the arcades: at night, enjoy the square quietly." },
  { id: "placa-sant-felip-neri", name: "Plaça de Sant Felip Neri", img: "Plaça Sant Felip Neri.jpg", area: "Gothic Quarter", lat: 41.3834, lng: 2.1751, tags: ["history",'culture'],
    story: "This is one of the quietest corners of the old town, and one of the saddest. Look at the church façade: it is pitted with holes. They are scars from a bombing raid in January 1938, during the Spanish Civil War, when bombs fell on the square and killed dozens of people, many of them children. The marks were left on purpose, so that no one forgets.",
    tip: "There is a school on the square: please keep your voice low." },
  { id: "temple-august", name: "Temple d'August", img: "Columnes del temple d'August (II).jpg", area: "Gothic Quarter", lat: 41.3834, lng: 2.1772, tags: ["history"],
    story: "Hidden inside a small courtyard on Carrer del Paradís stand four Roman columns, nearly two thousand years old. They belonged to the temple dedicated to the emperor Augustus, built on the highest point of the Roman town of Barcino, a small hill called Mont Tàber. Outside the door, look for a round millstone set into the pavement: it marks the top of that hill.",
    tip: "Entry to the courtyard is free; step in quietly, it's a working building." },
  { id: "placa-sant-jaume", name: "Plaça de Sant Jaume", img: "Barcelona - Plaça Sant Jaume.jpg", area: "Gothic Quarter", lat: 41.3826, lng: 2.177, tags: ["history", "local",'sports'],
    story: "Stand in the middle and turn around: on one side is the Palau de la Generalitat, home of the Catalan government, and facing it is Barcelona's City Hall. Two governments looking at each other across one square. This was already the heart of the city in Roman times, when the forum stood here. It's still where people gather to celebrate, protest and watch human towers on festival days.",
    tip: "Walk round the corner into Carrer del Bisbe to see Sant Jordi carved on the Generalitat's Gothic façade." },
  { id: "fossar-moreres", name: "Fossar de les Moreres", img: "Fossar de les Moreres Placa.JPG", area: "El Born", lat: 41.3837, lng: 2.1823, tags: ["history"],
    story: "This small, sloping square beside Santa Maria del Mar was a cemetery for the defenders who died during the siege of Barcelona, which ended on 11 September 1714. Read the inscription: it says that no traitor is buried here. Today the red arch and the eternal flame make it a place of memory, and every 11 September, Catalonia's national day, people gather here to remember.",
    tip: "It's a memorial, not a meeting point: keep it calm and respectful." },
  { id: "antic-hospital", name: "Antic Hospital de la Santa Creu", img: "208 Hospital de la Santa Creu, pati.jpg", area: "El Raval", lat: 41.3809, lng: 2.17, tags: ["history", "architecture", "outdoors"],
    story: "For more than five hundred years this Gothic building was the city's main hospital, founded in 1401. In 1926 an old man hit by a tram was brought here, so poorly dressed that nobody recognised him at first. It was Antoni Gaudí, and he died here a few days later. Today the building holds the National Library of Catalonia, and its courtyard of orange trees is a quiet green refuge.",
    tip: "The courtyard is free and shady: a perfect place to rest your feet." },
  { id: "refugi-307", name: "Refugi 307", img: "Refugi 307 1.JPG", area: "Poble-sec", lat: 41.3714, lng: 2.1666, tags: ["history"],
    story: "Behind this door is a network of tunnels dug by the neighbours of Poble-sec themselves during the Spanish Civil War, to shelter from the bombing raids on Barcelona. Families, children and older people dug by hand, and built benches, a fountain and even a small infirmary inside. It's one of more than a thousand shelters dug across the city, and one of the best preserved.",
    tip: "Visits are guided and need booking in advance through the City History Museum (MUHBA)." },
  { id: "drassanes", name: "Drassanes Reials", img: "Treballs de restauració Drassanes Reials de Barcelona (6).JPG", area: "El Raval", lat: 41.3755, lng: 2.1764, tags: ["history", "architecture"],
    story: "These huge stone halls were the royal shipyards of Barcelona, where galleys were built for the Crown of Aragon's fleet in the Middle Ages. Step back and look at the long rows of Gothic arches: they were made wide and high so whole ships could be built under cover. Today the shipyards house the Maritime Museum, one of the finest medieval industrial buildings in the world.",
    tip: "Look at the arches from the entrance hall even if you don't visit the museum." },
  { id: "palau-guell", name: "Palau Güell", img: "Facade of Gaudi's Casa Guell - Barcelona - Spain (14327581624).jpg", area: "El Raval", lat: 41.3788, lng: 2.1742, tags: ["architecture", "art"],
    story: "Gaudí built this mansion in the late 1880s for his patron, the industrialist Eusebi Güell, on a narrow street just off the Rambla. Look at the two parabolic arches of the entrance, wide enough for horse-drawn carriages, and the iron coat of arms of Catalonia between them. Up on the roof, out of sight from here, a forest of chimneys covered in broken tiles hints at the playful Gaudí to come.",
    tip: "Look up at the wrought ironwork over the doors: it's one of Gaudí's earliest masterpieces in iron." },
  { id: "casa-vicens", name: "Casa Vicens", img: "Barcelona, casa Vicens (Antoni Gaudí) balcón.jpg", area: "Gràcia", lat: 41.4035, lng: 2.1506, tags: ["architecture", "art"],
    story: "This colourful house was Antoni Gaudí's first important building, designed in the 1880s as a summer home when Gràcia was still a separate town surrounded by fields. Notice the green and white tiles decorated with small yellow flowers: Gaudí was inspired by the marigolds growing on the plot. The mix of brick, tiles and Moorish details shows a young architect already breaking the rules.",
    tip: "It's on a narrow residential street: admire it from the pavement without blocking neighbours' doors." },
  { id: "casa-punxes", name: "Casa de les Punxes", img: "Casa de les Punxes - 001.jpg", area: "Eixample", lat: 41.398, lng: 2.164, tags: ["architecture"],
    story: "With its pointed towers, this building looks like a castle from a northern European fairy tale dropped onto Avinguda Diagonal. Locals call it the House of Spikes. It was designed in the early 1900s by Josep Puig i Cadafalch, one of the great architects of Catalan Modernisme, as flats for three sisters. Look for the ceramic panels on the façade, including one of Sant Jordi, Catalonia's patron saint.",
    tip: "Cross to the other side of the Diagonal for the best view of all six towers." },
  { id: "fundacio-tapies", name: "Fundació Antoni Tàpies", img: "Fundació Antoni Tàpies, Barcelona 05.jpg", area: "Eixample", lat: 41.3916, lng: 2.1637, tags: ["art", "architecture"],
    story: "Look up at the roof: that tangle of metal wire is a sculpture called Cloud and Chair, by Antoni Tàpies, one of Catalonia's most important 20th-century artists. Underneath it stands a red-brick building by the Modernista architect Lluís Domènech i Montaner, originally a publishing house. Old and new art meet here: a 19th-century building crowned by a modern artwork.",
    tip: "Even without entering, the façade and the rooftop sculpture are worth a pause." },
  { id: "cccb", name: "CCCB", img: "Barcelona - Centre de Cultura Contemporània de Barcelona (CCCB).jpg", area: "El Raval", lat: 41.3837, lng: 2.1662, tags: ["art", "local"],
    story: "This cultural centre lives inside the old Casa de la Caritat, a former charity house. When it was renovated, the architects cut away one side of the courtyard and added a tall glass wall that leans forward. Stand in the courtyard and look up: the glass reflects the rooftops of the Raval and the hills behind the city. It hosts exhibitions, talks and festivals all year round.",
    tip: "The courtyard is free to enter and often has outdoor events in summer." },
  { id: "rambla-raval", name: "Rambla del Raval", img: "Gat Gato Cat (371758010).jpg", area: "El Raval", lat: 41.3788, lng: 2.1691, tags: ["local", "art"],
    story: "This wide avenue is much younger than it looks: it was opened around the year 2000 by knocking down several crowded blocks of the Raval to bring in light and air. At one end sits a huge bronze cat by the Colombian artist Fernando Botero, a favourite with local children. Around it, shops and cafés from dozens of countries show how international this neighbourhood has become.",
    tip: "This is a real neighbourhood high street: support the small local shops." },
  { id: "cap-barcelona", name: "Barcelona Head", img: "At Barcelona 2019 054.jpg", area: "Port Vell", lat: 41.3809, lng: 2.1825, tags: ["art", "outdoors"],
    story: "This giant face by the American pop artist Roy Lichtenstein was made for the 1992 Olympic Games. Look closely: it's covered in pieces of broken ceramic, the trencadís technique Gaudí made famous, but arranged like the dots of a comic strip. It's a playful meeting between American pop art and Catalan Modernisme, standing by the old port.",
    tip: "Walk a few steps back towards the sea to see the whole face against the sky." },
  { id: "placa-vila-gracia", name: "Plaça de la Vila de Gràcia", img: "Barcelona Gràcia 093 (8277950946).jpg", area: "Gràcia", lat: 41.4002, lng: 2.1576, tags: ["local", "history", "architecture"],
    story: "This square was the heart of Gràcia when it was still an independent town, before it joined Barcelona in 1897. Look up at the slender clock tower: it was built in the 1860s and has become the symbol of the neighbourhood. Opposite stands Gràcia's district hall. During the Festa Major in August, giant figures dance here and the whole square fills with music.",
    tip: "Neighbours live all around the square: in the evening, keep the noise down." },
  { id: "placa-virreina", name: "Plaça de la Virreina", img: "Església de Sant Joan de Gràcia, Barcelona, Plaça de la Virreina, Barcelona.jpg", area: "Gràcia", lat: 41.4049, lng: 2.1572, tags: ["local", "outdoors"],
    story: "Small, quiet and lined with trees, this square is one of Gràcia's favourite places for a coffee in the shade. At one end stands the church of Sant Joan, rebuilt after it was burned during the Civil War. Watch how the square works: parents with prams, older neighbours on the benches, friends on the terraces. Gràcia's squares are its living rooms.",
    tip: "It's a calm residential square: sit, enjoy, and keep voices low." },
  { id: "mercat-barceloneta", name: "Mercat de la Barceloneta", img: "Mercat de la Barceloneta - panoramio.jpg", area: "La Barceloneta", lat: 41.3804, lng: 2.1892, tags: ["food", "local", "architecture"],
    story: "The fishermen's neighbourhood has had a market here since the 19th century. The old iron structure was renovated in 2007, and the architects added a bold new roof with solar panels that seems to float above it. Inside, look for fresh fish and seafood, of course, and small bars where locals have lunch at the counter.",
    tip: "Most Barcelona markets close on Sundays and many stalls close in the afternoon." },
  { id: "mercat-concepcio", name: "Mercat de la Concepció", img: "Mercat de la Concepció - façana Aragó.jpg", area: "Eixample", lat: 41.3959, lng: 2.1686, tags: ["food", "local"],
    story: "Built in the late 19th century, this iron-and-glass market serves the right side of the Eixample. It's especially known for its flower stalls, which spill colour onto the street outside. Inside, it's a real neighbourhood market: fruit, meat, fish and cheese, with very few tourists. A good place to see how locals in the Eixample really shop.",
    tip: "Buy something if you linger: the stalls are people's livelihoods, not a museum." },
  { id: "mercat-abaceria", name: "Mercat de l'Abaceria Central", img: "Mercat de l'Abaceria Central.JPG", area: "Gràcia", lat: 41.4021, lng: 2.1595, tags: ["food", "local"],
    address: "Travessera de Gràcia, 186 · Carrer de Puigmartí",
    story: "This is Gràcia's biggest market and one of the busiest neighbourhood markets in the city, serving local families since the end of the 19th century. After a long renovation and years in a temporary tent, it reopened in its rebuilt building in November 2026. Either way, it's where Gràcia buys its fruit, fish and bread, far from the tourist routes.",
    tip: "Buy something if you linger: the stalls are people's livelihoods. In the first weeks after the reopening, some stalls may still be settling in." },
  { id: "mercat-ninot", name: "Mercat del Ninot", img: "01 Mercat del Ninot, c. Mallorca.jpg", area: "Eixample", lat: 41.3882, lng: 2.1542, tags: ["food"],
    story: "Ninot means a little figure or doll in Catalan. The market takes its name from a carved wooden figurehead from a ship that once hung outside a nearby tavern. Today the market has a modern building, rebuilt in the 2010s, and it's a favourite with local food lovers for its fish, seafood and good-quality produce.",
    tip: "Mornings are best: that's when the stalls are full and the neighbourhood does its shopping." },
  { id: "bunkers-carmel", name: "Turó de la Rovira (Bunkers del Carmel)", img: "Bunkers del Carmel Barcelona.jpg", area: "El Carmel", lat: 41.4194, lng: 2.1617, tags: ["outdoors", "history"], crowded: true,
    story: "From this hilltop you can see almost the whole city, from the sea to the mountains. That's exactly why anti-aircraft guns were placed here during the Spanish Civil War, to defend Barcelona from bombing raids. After the war, families who had nowhere else to live built shacks among the ruins, and they lived here until the late 1980s. The concrete platforms are what remains.",
    tip: "A heritage site above people's homes: no parties or music, take your rubbish with you, and keep voices down on the way up." },
  { id: "port-vell", name: "Port Vell", img: "Port Vell, Barcelona, Spain - Jan 2007.jpg", area: "Port Vell", lat: 41.3759, lng: 2.1793, tags: ["outdoors"],
    story: "This is Barcelona's old port, where the city met the sea for centuries. The wooden walkway in front of you, the Rambla de Mar, swings open to let boats pass. Look back towards the city: the Columbus monument stands at the end of the Rambla. Since the 1992 Olympics, this old working harbour has become a promenade for walking, cycling and watching the boats.",
    tip: "It's a lovely place at sunset: find a bench and watch the boats come in." },
  { id: "parc-estacio-nord", name: "Parc de l'Estació del Nord", img: "092 Parc de l'Estació del Nord (Barcelona), al centre l'escultura Cel caigut.jpg", area: "Eixample", zone: "poblenou", lat: 41.3944, lng: 2.185, tags: ["outdoors", "art"],
    story: "This park was created on old railway land next to the former North Station. Look at the ground: the long, wave-like forms covered in blue ceramic are a land-art work by the American artist Beverly Pepper, called Fallen Sky. Children climb them, dogs run around them and neighbours read in the sun. Art here is something you walk on, not just look at.",
    tip: "A quiet, little-known park: perfect for a break away from the crowds." },
  { id: "jardins-palau-robert", name: "Jardins del Palau Robert", img: "Barcelona - Jardins del Palau Robert 01.jpg", area: "Eixample", lat: 41.3957, lng: 2.1589, tags: ["outdoors", "architecture"],
    story: "Just off the busy Passeig de Gràcia hides a small garden with tall palm trees, behind an elegant palace built at the turn of the 20th century. Today the palace is a public information centre about Catalonia, and the garden is free to enter. It's a surprising pocket of calm only a few steps from one of the city's busiest shopping streets.",
    tip: "The garden is free: take a break here before going back into the crowds on Passeig de Gràcia." },
  { id: "platja-sant-sebastia", name: "Platja de Sant Sebastià", img: "14-08-06-barcelona-RalfR-015.jpg", area: "La Barceloneta", lat: 41.3713, lng: 2.1893, tags: ["outdoors", "local"],
    story: "This is one of the oldest beaches in the city: in the 19th century, Barcelona's first bathing clubs opened here, when sea bathing became fashionable. Today some of the city's historic swimming clubs still stand at the edge of the sand. Look to the end of the beach: the sail-shaped hotel marks where the city now ends and the open sea begins.",
    tip: "Wear a top when you walk back into the neighbourhood streets: it's a local request, and the law." },
  // Added for the Sports and Culture interests.
  { id: "font-canaletes", name: "Font de Canaletes", img: "Barcelona - Rambla de Canaletes - View NE.jpg", area: "La Rambla", lat: 41.3852, lng: 2.1702, tags: ["sports", "local", "history"], crowded: true,
    story: "This iron fountain at the top of the Rambla carries two traditions. The first is a legend: whoever drinks from it will always come back to Barcelona. The second belongs to football. For decades, Barça fans have gathered right here to celebrate every big win, singing and waving flags until late at night. On an ordinary day it's just a fountain where neighbours fill a bottle; on a title night, the whole Rambla turns blue and red.",
    tip: "On match nights this spot gets packed: if you come to celebrate, respect the people who live on the Rambla." },
  { id: "gimnas-sole", name: "Gimnàs Solé", img: "34 Fundació del F.C. Barcelona, c. Montjuïc del Carme.jpg", area: "El Raval", lat: 41.3828, lng: 2.17, tags: ["sports", "history"],
    address: "Carrer de Montjuïc del Carme, 5 · Carrer del Pintor Fortuny",
    story: "Nothing about this narrow street suggests history, yet FC Barcelona was born here. On 29 November 1899, a group of football enthusiasts led by the Swiss Joan Gamper met at the Gimnàs Solé, a gymnasium in this street, and founded the club after Gamper had placed an advert in a sports newspaper looking for players. Today a plaque recalls that evening. From a small gym in the Raval to one of the most famous clubs in the world.",
    tip: "It's a residential street: look for the plaque quietly and don't block doorways." },
  { id: "nou-sardenya", name: "Nou Sardenya", img: "NouSardenya.jpg", area: "Gràcia", lat: 41.4118, lng: 2.1615, tags: ["sports", "local"],
    story: "Barcelona has another historic football club, and this is its home. CE Europa was founded in 1907 in Gràcia, and in 1929 it played in Spain's very first national league, alongside the biggest clubs in the country. Its small stadium is squeezed between apartment blocks, so neighbours can almost watch matches from their balconies. Europa is a true neighbourhood club, with loyal, passionate fans who see it as part of Gràcia's identity.",
    tip: "If there's a home match, buying a ticket is a great way to see local football up close." },
  { id: "club-natacio", name: "Club Natació Barcelona", img: "Club Natació Barcelona.jpg", area: "La Barceloneta", lat: 41.3715, lng: 2.1884, tags: ["sports", "outdoors"],
    story: "This club on Barceloneta beach was founded in 1907 and is one of the oldest swimming clubs in Spain. It has produced generations of swimmers and water polo players, a sport Barcelona has always been strong at. Every Christmas Day since its early years, the club has organised a traditional swim in the port, the Copa Nadal: brave swimmers jump into the cold winter sea while crowds cheer from the quay.",
    tip: "The club is for members, but the beach in front of it is open to everyone." },
  { id: "port-olimpic", name: "Port Olímpic", img: "Port Olimpic. Torres Mapfre.jpg", area: "Vila Olímpica", lat: 41.3861, lng: 2.1998, tags: ["sports", "outdoors", "history"],
    story: "This whole neighbourhood was built for the 1992 Olympic Games. Old factories and railway lines were cleared to create the Olympic Village, where the athletes lived, and this port, where the sailing events were based. Look up at the two towers rising over the beach and at Frank Gehry's giant golden fish sculpture shining in the sun. The Games changed Barcelona for ever: they opened the city to the sea.",
    tip: "Walk along the promenade towards Barceloneta for one of the best seafront strolls in the city." },
  { id: "liceu", name: "Gran Teatre del Liceu", img: "Gran Teatre del Liceu, façana Rambla.jpg", area: "La Rambla", lat: 41.3802, lng: 2.1734, tags: ["culture", "history", "architecture"],
    story: "Behind this modest façade on the Rambla hides one of Europe's great opera houses, opened in 1847. Its story is dramatic: it burned down in 1861, and in 1893 an anarchist threw bombs into the audience during a performance. In 1994 another fire destroyed it again, and the whole city helped rebuild it. It reopened in 1999, and its red and gold auditorium is once again the heart of opera in Barcelona.",
    tip: "Guided tours run most days, and last-minute tickets can be surprisingly affordable." },
  { id: "teatre-romea", name: "Teatre Romea", img: "Teatre Romea - Barcelona (Catalonia).jpg", area: "El Raval", lat: 41.3805, lng: 2.1711, tags: ["culture", "history"],
    story: "This theatre on Carrer de l'Hospital has been staging plays since 1863, and for much of its history it was the home of theatre in Catalan. Generations of Catalan actors and playwrights made their names on this stage, even in years when the language was pushed out of public life. Today it still presents modern productions, mostly in Catalan, for a local audience.",
    tip: "Check the programme: some productions offer surtitles." },
  { id: "el-molino", name: "El Molino", img: "Fachada Rosa Puig retoc opt.jpg", area: "Poble-sec", lat: 41.3746, lng: 2.1672, tags: ["culture", "local", "history"],
    story: "Look for the windmill on the façade: this is El Molino, Barcelona's most famous cabaret, open since the early 20th century and inspired by the Moulin Rouge in Paris. The Avinguda del Paral·lel around it was once the city's Broadway, lined with theatres, music halls and cafés where workers came to laugh, sing and forget a hard week. El Molino survived when most of them closed, and it still puts on shows today.",
    tip: "People live above the theatres on the Paral·lel: keep it calm when shows let out." },
  { id: "filmoteca", name: "Filmoteca de Catalunya", img: "Filmoteca de Catalunya-seu Raval.JPG", area: "El Raval", lat: 41.3785, lng: 2.171, tags: ["culture"],
    story: "This bold concrete building, opened in 2012, is home to Catalonia's film archive. Inside, cinemas show classics, retrospectives and rare films every day at low prices, and the archive looks after decades of Catalan cinema. Its arrival in this corner of the Raval was part of a plan to bring culture and new life to one of the city's oldest and most crowded neighbourhoods.",
    tip: "Tickets are cheap: catching a classic film here is a lovely local evening." },
  { id: "placa-orwell", name: "Plaça de George Orwell", img: "405 Plaça de George Orwell (Barcelona), escultura de Leandre Cristòfol.jpg", area: "Gothic Quarter", lat: 41.3805, lng: 2.1774, tags: ["culture", "history"],
    story: "This small square carries the name of the English writer George Orwell. In 1936 he came to Barcelona to fight for the Republic in the Spanish Civil War, and he described the city in those intense months in his book Homage to Catalonia. Today the square is a lively meeting point in the Gothic Quarter, with terraces and neighbours chatting, a long way from the barricades Orwell wrote about.",
    tip: "Neighbours live around the square: enjoy the terraces, but keep the noise down at night." },
  { id: "arc-teatre", name: "Arc del Teatre", img: "Carrer de l'Arc del Teatre Barcelona.JPG", area: "El Raval", lat: 41.3769, lng: 2.1737, tags: ["culture"],
    story: "Step under this arch off the Rambla and you enter the world of a novel. In The Shadow of the Wind, by Carlos Ruiz Zafón, one of the best-selling Spanish books ever, a young boy is led through these streets to a secret library called the Cemetery of Forgotten Books, hidden behind a door in this very passage. The place is fictional, but readers from all over the world come to imagine which door it might be.",
    tip: "It's a narrow residential street: please don't knock on doors looking for the library." },
  { id: "la-central", name: "La Central del Raval", img: "Jardí i capella de la Casa de la Misericòrdia.jpg", area: "El Raval", lat: 41.3836, lng: 2.1689, tags: ["culture"],
    story: "This bookshop lives inside a former chapel on Carrer d'Elisabets. Instead of an altar, there are tables piled with novels, art books and essays under the old stone vaults. It's one of the city's favourite independent bookshops, a place where locals come to browse slowly, and it shows how the Raval's old religious buildings have found new lives as places of culture.",
    tip: "Browse quietly, as you would in a library, and support the shop if you find something you like." },

  // Added 14 Nov 2026 (approved list after the external review). Texts in all 7 languages,
  // practical cards and sources live in content/manual/<id>.json (see scripts/import-manual.mjs).
  { id: "sant-pau-del-camp", name: "Sant Pau del Camp", img: "Sant Pau del Camp Facade.jpg", area: "El Raval", lat: 41.3763, lng: 2.1697, tags: ["architecture", "history"],
    address: "Carrer de Sant Pau, 101",
    story: "Look at the small stone church in front of you: it is one of the oldest buildings in Barcelona. Its name, Sant Pau del Camp, means Saint Paul in the fields, because it stood in open country, outside the medieval city walls. The monastery is documented from the 10th century, and it was sacked in 985, when al-Mansur's troops attacked Barcelona. What you see today is mostly a Romanesque rebuilding. Now look closely at the doorway: the two capitals on its columns are much older, reused marble pieces from Visigothic times. Above them, Christ sits between Saint Peter and Saint Paul.",
    tip: "It is still a parish church: if you go in, avoid service times and keep your voice down." },
  { id: "sant-pere-puelles", name: "Sant Pere de les Puel·les", img: "Barcelona - Església de Sant Pere de Puelles.jpg", area: "Sant Pere", lat: 41.3894, lng: 2.179, tags: ["history", "architecture"],
    address: "Plaça de Sant Pere",
    story: "This square, and the streets of Sant Pere around it, take their name from the church in front of you. In the 10th century, Count Sunyer and Countess Riquilda founded a convent of Benedictine nuns here, outside the city walls, and its church was consecrated in 945. The nuns were known as puel·les, from the Latin word for young women. Don't be fooled by the medieval look. The convent was attacked in 985, a new church was consecrated in the 12th century, and fires in 1909 and during the Civil War forced more rebuilding. Very little of the first building survives.",
    tip: "Neighbours live all around this square and it is still a church: listen from the open side, away from the doors and steps." },
  { id: "biblioteca-arus", name: "Biblioteca Pública Arús", img: "Biblioteca Pública Arús de Barcelona (2).JPG", area: "Eixample", lat: 41.3928, lng: 2.1788, tags: ["history", "culture"],
    address: "Passeig de Sant Joan, 26",
    story: "Look for the iron sign on the façade: Biblioteca Pública Arús. Behind this ordinary-looking building is a library born from a will. When the writer and freemason Rossend Arús died in 1891, he left his own flat and his books to create a library for the education of working people. It opened in 1895. Today its shelves hold one of the great collections on the workers' movement, anarchism and freemasonry, and, as a surprise, a collection devoted to Sherlock Holmes. In the hall, a small bronze Statue of Liberty welcomes readers. It is still a working library, a reading room before it is a sight.",
    tip: "It is a working library: listen out here, and inside keep silent and don't photograph readers." },
  { id: "via-sepulcral-romana", name: "Via Sepulcral Romana", img: "Via Sepulcral Romana Plaça Villa de Madrid 01.jpg", area: "Gothic Quarter", lat: 41.3843, lng: 2.1722, tags: ["history"],
    address: "Plaça de la Vila de Madrid",
    story: "Lean on the railing and look down: you are looking at Roman graves. In Roman times the dead were buried outside the town, along the roads that led out of it, and this was one of the roads leaving the colony of Barcino. Graves were placed along it from the 1st to the 3rd century. Look for the stones shaped like half-barrels lying on the ground: they are cupae, a kind of Roman tomb. Much later a convent stood on this spot. The remains were found when the site was rebuilt after the Civil War, and they were left where they lay, so the square was built around them.",
    tip: "You don't need a ticket to see the graves from the square: take your turn at the railing and leave room for others." },
  { id: "escola-industrial", name: "Recinte de l'Escola Industrial", img: "Escola industrial.jpg", area: "Eixample", lat: 41.388, lng: 2.1493, tags: ["architecture", "history"],
    address: "Carrer del Comte d'Urgell, 187",
    story: "Look at the long brick buildings around you. In the late 1860s this was the textile factory of the Batlló family, designed by the architect Rafael Guastavino, at a time when Barcelona was filling up with mills. The factory did not last long. At the beginning of the 20th century the site was bought to create the Escola Industrial, a school to train the engineers and technicians that industrial Catalonia needed. Look for the clock that gives one of the buildings its name, the Edifici del Rellotge. Today the same walls that once held looms hold classrooms, laboratories and a student residence.",
    tip: "It is a working campus: stay on the open paths, don't go into the buildings, and keep your voice down near the classrooms." },
  { id: "diposit-aigues", name: "Dipòsit de les Aigües", img: "Dipòsit de les Aigües, Wellington (I).jpg", area: "Vila Ol\u00edmpica", zone: "poblenou", lat: 41.3904, lng: 2.1889, tags: ["architecture", "history"],
    address: "Carrer de Wellington, 46–48",
    story: "Look at this huge brick building with a tower at each corner. It was built between 1874 and 1880 as a water tank, designed by Josep Fontserè, the architect of the Ciutadella park, to feed the park's great cascade and water its gardens. The water was held up on top, and underneath a forest of brick pillars and arches carried its weight. Later the building had many lives: a shelter for poor people, a store for the fire brigade, a garage for police vehicles. Since 1999 it has been a library of the Universitat Pompeu Fabra, where students read among those same brick arches.",
    tip: "It is a university library: enjoy it from the street and keep the entrance clear for students." },
  { id: "can-framis", name: "Museu Can Framis", img: "Barcelona - Museu Can Framis (1).jpg", area: "Poblenou", zone: "poblenou", lat: 41.4029, lng: 2.195, tags: ["art", "architecture", "history"],
    address: "Carrer de Roc Boronat, 116–126",
    story: "Look at the brick buildings and the tall chimney behind them. This was the wool factory of the Framis family, from the days when Poblenou was so full of mills that people called it the Catalan Manchester. When the old industrial land was transformed, two of the three factory buildings were restored and the third was rebuilt in concrete, by the architects of BAAS. Since 2009 it has been a museum of contemporary painting run by the Fundació Vila Casas: around two hundred and fifty works by Catalan artists from the 1960s onwards. By the entrance, look for the sculpture Dell'Arte, by Jaume Plensa.",
    tip: "The square in front is open to everyone; the museum itself has a ticket and opening hours." },
  { id: "farinera-clot", name: "La Farinera del Clot", img: "111 La Farinera del Clot (Barcelona), des del c. Independència.jpg", area: "El Clot", zone: "poblenou", lat: 41.4052, lng: 2.1882, tags: ["history", "architecture", "local"],
    address: "Gran Via de les Corts Catalanes, 837",
    story: "Look at this red-brick building with its ceramic details. It was a flour mill, the Farinera de Sant Jaume. A mill was first planned here in 1879, and in 1908 the architect Josep Maria Pericas built the Modernista factory you see now. Flour was made here until 1991. Then the city bought the site, kept the main building and turned it into a cultural centre, which opened in 1999. Since 2004 it has been run by the Clot's own associations, the first cultural centre in Barcelona managed by a federation of local groups. Instead of flour, it now makes concerts, classes and exhibitions.",
    tip: "It is the neighbourhood's own cultural centre: keep the entrance clear and don't interrupt classes or rehearsals." },
  { id: "disseny-hub", name: "Disseny Hub (Museu del Disseny)", img: "Barcelona - Disseny Hub Barcelona, Museu del Disseny de Barcelona 1.jpg", area: "El Clot", lat: 41.4025, lng: 2.1881, tags: ["architecture", "art"],
    address: "Plaça de les Glòries Catalanes, 37–38",
    story: "Look at this dark building that seems to hang in the air, with a huge overhang reaching out over the square. People nicknamed it the stapler. It is the Disseny Hub, designed by the studio MBM and built between 2008 and 2013, and since 2014 it has been home to the Museu del Disseny, Barcelona's design museum. Inside, it brings together the collections of four older museums: decorative arts, ceramics, textiles and fashion, and graphic arts, more than seventy thousand objects. Now look around you. Glòries was for decades a huge road junction, and it is slowly being turned into a park.",
    tip: "The square outside is a public space; the museum has a ticket and opening hours. Keep cycle lanes and the park paths clear." },
];
